from html import escape

def media_features(lang):
 def t(zh,en): return zh if lang=='zh' else en
 def shot(name,zh,en):
  return f'<button class="media-shot" data-zoom-src="assets/screens/{name}.png" aria-label="{t("放大：","Enlarge: ")+t(zh,en)}"><img src="assets/screens/{name}.png" alt="{t(zh,en)}" loading="lazy" width="1080" height="2424"></button>'
 s=f'''<section class="section media-features" id="virtual-media"><div class="section-heading"><p class="eyebrow">NEW / CAMERA & MICROPHONE</p><h2>{t('画面和声音，','Your picture. Your sound.')}<br><em>{t('都可以自己选。','Your choice.')}</em></h2><p>{t('给应用换一段视频，给镜头换个背景，或先试听再选一个音色。星轨新增虚拟摄像头与虚拟麦克风，按应用、按分身分别设置。','Use a video as your camera feed, change the background, or audition a voice before choosing it. Orbit’s virtual camera and microphone have separate settings for each app and clone.')}</p></div>
 <div class="media-feature-grid"><article class="media-camera"><div class="media-feature-copy"><p class="eyebrow">VIRTUAL CAMERA</p><h3>{t('镜头里，放你准备好的内容。','Put your own content on camera.')}</h3><p>{t('图片、视频，都能成为摄像头的画面来源。调整大小、位置、旋转和分辨率，横屏竖屏各有合适的构图。','Choose an image or video as the camera source. Adjust its size, position, rotation and resolution to frame it for portrait or landscape.')}</p><ul><li>{t('适应、裁切、拉伸三种显示方式','Fit, crop or stretch the picture')}</li><li>{t('视频循环播放，同一素材可实时调整构图','Loop a video and adjust its framing live')}</li><li>{t('暂离画面，或切回系统摄像头','Choose an away screen or switch back to the system camera')}</li></ul></div>{shot('media-framing','画面构图编辑页：比例、大小、位置和旋转','Framing editor: aspect ratio, size, position and rotation')}<p class="media-caption">{t('实际设置页 · Android 17 参考环境 · 测试色块素材','Actual settings screen · Android 17 reference environment · Color test source')}</p></article>
 <article class="media-microphone"><div class="media-feature-copy"><p class="eyebrow">VIRTUAL MICROPHONE</p><h3>{t('声音，也有自己的设置。','Give your audio its own settings.')}</h3><p>{t('使用音频文件、视频原声或实时变声作为麦克风输入。摄像头和麦克风可以各选各的，也可以一起跟随同一段视频。','Use an audio file, a video’s original audio, or live voice processing as the microphone input. Choose picture and sound independently, or link both to the same video.')}</p></div><div class="media-wave" aria-hidden="true">'''
 for i in range(47):
  h=18+((i*37+i*i*11)%105)
  s+=f'<i style="height:{h}px"></i>'
 s+=f'''</div><p class="media-caption">{t('声音功能示意，非实测波形','Audio illustration, not a measured waveform')}</p><div class="media-voice-copy"><h4>{t('先听一听，再决定。','Hear it before you choose.')}</h4><p>{t('自然、低沉、温暖、清亮、轻扬五档预设，音调与共振峰也能单独调整。录一段 3 秒声音，对比原声与变声效果。','Choose from five presets—natural, deep, warm, clear and light—or adjust pitch and formant separately. Record three seconds and compare the original with the processed voice.')}</p><div class="media-tags">'''
 for a,b in [('自然','Natural'),('低沉','Deep'),('温暖','Warm'),('清亮','Clear'),('轻扬','Light')]:s+=f'<span>{t(a,b)}</span>'
 s+=f'''</div><p>{t('已有训练好的音色？可导入兼容的 LLVC 模型包并试听，按分身保存。','Have a trained voice model? Import and audition a compatible LLVC package, with settings saved per clone.')}</p></div></article></div>
 <article class="media-background"><div class="media-feature-copy"><p class="eyebrow">PORTRAIT BACKGROUNDS</p><h3>{t('背景换了，构图也能细调。','Change the scene. Refine the frame.')}</h3><p>{t('办公室、会议室、客厅、工作室，四种内置背景可选；也能使用纯色或自己的图片。实时预览人像，调整边缘平滑、轮廓、人像大小与左右位置。','Choose an office, meeting room, living room or studio, a solid color, or your own image. Preview the portrait and adjust edge smoothing, edge trim, size and horizontal position.')}</p><div class="media-scene-grid">'''
 for n,a,b in [('office','办公室','Office'),('meeting','会议室','Meeting room'),('living','客厅','Living room'),('studio','工作室','Studio')]:s+=f'<figure><img src="assets/media/portrait-scene-{n}.webp" alt="{t(a,b)}" loading="lazy" width="1440" height="810"><figcaption>{t(a,b)}</figcaption></figure>'
 s+=f'''</div><p class="media-caption">{t('产品内置背景素材 · AI 生成场景','Backgrounds included in the product · AI-generated scenes')}</p></div><figure>{shot('media-scenes','人像背景场景选择器的实际界面','Actual portrait background scene picker')}<figcaption class="media-caption">{t('实际设置页 · Android 17 参考环境','Actual settings screen · Android 17 reference environment')}</figcaption></figure></article>
 <div class="media-mode-grid">'''
 for a,b,c,d in [
 ('只换画面，保留麦克风。','Change the picture. Keep your microphone.','选视频时保留原来的麦克风来源，画面与声音独立配置。','Keep the existing microphone source when selecting a video, with independent picture and audio settings.'),
 ('画面与原声，一起用。','Use the video’s picture and audio.','带音轨的视频可联动两路输入；麦克风页可以恢复之前的独立来源。','Link both inputs to a video with an audio track. Restore the previous independent microphone source from its settings.'),
 ('文件之外，还能接来源插件。','Connect more sources with plugins.','支持网络 MJPEG 画面和 L16 音频来源，并提供独立插件 SDK。','Network MJPEG video and L16 audio sources are supported, with an SDK for independent source plugins.')]:s+=f'<article><h3>{t(a,b)}</h3><p>{t(c,d)}</p></article>'
 s+=f'''</div><details class="media-validation"><summary>{t('查看实测范围与使用说明','Test coverage and usage notes')}</summary><div class="media-validation-body"><div><h3>{t('从实际采集到录制回放。','From capture to recording and playback.')}</h3><p>{t('2026 年 11 月 21–24 日记录：小米 12 Pro / Android 15 验证文件画面、音频样本、实时变声和训练模型采集；Android 17 参考环境验证背景、构图和来源切换。小米 17 的媒体工作台有录制、回放及导出记录。','Records from November 21–24, 2026: Xiaomi 12 Pro / Android 15 tests cover file video, audio samples, live voice processing and trained-model capture. Android 17 reference tests cover backgrounds, framing and source switching. Xiaomi 17 media-workbench records cover recording, playback and export.')}</p><p>{t('覆盖 Camera1、Camera2、CameraX、NDK 相机、AudioRecord、AAudio 与 MediaRecorder 的限定用例。不同接口的切换时机不同，部分需要重新打开采集或重启分身。','Bounded tests cover Camera1, Camera2, CameraX, NDK camera, AudioRecord, AAudio and MediaRecorder. Source-switch timing varies by interface; some paths require reopening capture or restarting the clone.')}</p><p>{t('网络来源仅做过本地连接验证。真实会议对端的画质、听感、延迟与回声消除仍需单独验证；录制文件已有约 60–80 ms 音画偏移记录，不宣称零延迟或所有会议 App 通用。模型导入支持约定的 LLVC 格式，不是任意模型或一句话克隆音色。','Network sources have local-connection tests only. Picture quality, voice quality, latency and echo reduction at a real meeting receiver still need separate validation. Recorded files have shown roughly 60–80 ms AV offset. These results do not establish zero latency or universal meeting-app support. Model import accepts the specified LLVC format, not arbitrary models or one-sentence voice cloning.')}</p></div><figure>{shot('media-workbench','小米17媒体工作台：采样、录制、播放与导出','Xiaomi 17 media workbench: capture, recording, playback and export')}<figcaption class="media-caption">{t('历史实机截图 · 媒体测试工作台','Historical device screenshot · Media test workbench')}</figcaption></figure></div></details></section>'''
 return s
